        // Que 17 (TÙY)
        list.add(new LineJudgment(17, 1, "Sơ Cửu", "初九: 官有渝, 貞吉, 出⾨交有功.", "Quan hữu thâu, trinh cát, xuất môn giao hữu công.", "Hào Chín Đầu: Quan có thay đổi, chính thì tốt, ra cửa kết bạn thì có công.", 337, null));
        list.add(new LineJudgment(17, 2, "Lục Nhị", "象⽈: 官有渝, 從正吉也, 出⾨交有功, 不失也. Dịch âm. - Tượng viết: Quan hữu thâu, tòng chính cát dã; xuất môn giao hữu công, bất thất dã. Dịch nghĩa. Lời Tượng nói rằng: Quan có thay đổi, theo chính tốt vậy; ra cửa kết bạn có công, không lỗi vậy. GIẢI NGHĨA Truyện của Trình Di. - Đã có chỗ theo mà thay đổi, ắt là sự theo được chính đính thì tốt; nếu mà sự theo không chính đính thì phải hối hận. Ra cửa kết bạn, thì không bị vướng về tình riêng, sự kết bạn đó ắt là chính đính. Chính đính thì không lỗi mà có công. LỜI KINH 六⼆:係⼩⼦,失丈夫.", "Hệ tiểu tử, thất trượng phu. Dịch nghũu -", "Hào Sáu Hai: Quâi quít kẻ tiểu tử, mất đấng trượng phu.", 338, null));
        list.add(new LineJudgment(17, 3, "Lục Tam", "象⽈:係⼩⼦,弗兼與也. Dịch âm. - Tượng viết: Hệ tiểu tử, phất kiêm dữ dã. Dịch nghĩa. - Lời Tượng nói rằng: Quấn quít kẻ tiểu tử, không gồm cùng vậy. GIẢI NGHĨA Truyện của Trình Đi. - Người ta thửa theo, được đằng ngay thì xa đằng cong, theo đằng trái thì mất đằng phải, không lẽ theo cả hai đằng. Hào Hai nếu quấn quít với hào Đầu thì mất hào Năm, thế là không thể gồm cùng. Nói vậy để răn người ta theo đằng ngay thì nên chuyên nhất. LỜI KINH 六三:係丈夫,失⼩⼦,隨有求,得利,居貞.", "Hệ trượng phu, thất tiểu tử, tùy hữu cầu, đắc lợi, cự trinh,", "Hào Sáu Ba: Quấn quít đấng trượng phu, mất kẻ tiểu tử, theo mà có tìm, lợi về ở trinh.", 339, null));
        list.add(new LineJudgment(17, 4, "Cửu Tứ", "象⽈:係丈夫,志舍下也. Dịch âm. - Tượng viết: Hệ trượng phu, chí xả hạ dã. Dịch nghĩa. - Lời Tượng nóỉ rằng: quấn quít đấng trượng phu chí bỏ kẻ dưới vậy. GIẢI NGHĨA Truyện của Trình Di. - Đã theo với trên, thì là chí nó bỏ dưới không theo.Bỏ dưới không theo, tức là bỏ thấp mà theo cao. Ở việc theo, như thế là phải. LỜI KINH 九四:隨有獲,貞凶.有孚在道,以明,何啓.", "Tùy hữu hoạch, trinh hung, hữu phu, tại đạo, dĩ minh, hà cữu?", "Hào Chín tư: Theo có được, chính mà hung; có tin, ở đạo, dùng sáng, lỗi gì?", 341, null));
        list.add(new LineJudgment(17, 5, "Cửu Ngũ", "象⽈: 隨有獲, 其義凶也, 有孚在道, 明功也. Dịch âm. - Tượng viết: Tùy hữu hoạch, kỳ nghĩa hung dã; hữu phu tại đạo, minh công dã.Dịch nghĩa. - Lời Tượng nói rằng: Theo có được, nghĩa nó hung vậy; có tin, ở đạo, công của sự sáng vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở ngôi gần vua mà có được, nghĩa nó chỉn hung. Có thể có từx mà ở đạo thì không có lỗi, đó là công của sự sáng khôn. Lời bàn của Tiên Nho. - Viên Mai Nham nói rằng: “Nghĩa nó hung” là có lẽ hung, mà chưa ắt hung, xử được phải đạo như mấy câu dưới, thì không có lỗi. LỜI KINH 九#:孚于嘉,吉.", "Phu vu gia, cát.", "Hào Chín Năm: Tin về kẻ lành, tốt.", 342, null));
        list.add(new LineJudgment(17, 6, "Thượng Lục", "象⽈:孚于嘉吉,位正中也. Dịch âm. - Tượng viết: Phu vu gia, cát, vị chính trung dã. Dịch nghĩá. - Lời Tượng nói rằng: Tin về kẻ lành, tốt, vì ở ngôi chính giữa vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở ngôi chính trung, theo đạo trung chính, thật bụng tin kẻ mình theo là kẻ chính trung, tức là kẻ lành, đủ biết là tốt. Kẻ lành mà nó đã tin là hào Sáu Hai. Sự theo ngược vừa độ là phải. Cái mà sự theo phải ngăn ngừa là sự quá đáng. Bỏi vì lòng mình vui đẹp mà theo, thì không biết là quá đáng. LỜI KINH 上六:拘係之,乃從維之,王⽤亨于西⼭.", "Câu hệ chi, nải tòng duy chi, vương dụng hưởng vu Tây sơn.", "Hào Sáu Trên: Cầm buộc đó, bèn theo ràng đó, vua dùng hưởng ở non Tây.", 343, null));

        // Que 18 (CỔ)
        list.add(new LineJudgment(18, 1, "Sơ Lục", "象⽈:⼭下有⾵,盛.君⼦以振民育德. Dịch âm. - Tượng viết: Sơn hạ hữu phong, Cổ, quân tử dĩ chấn dân dục đức. Dịch nghĩa. - Lời Tượng nói rằng: Dưới núi có gió, là quẻ Cổ, đấng quân tử coi đó mà nhức[5] dân nuôi đức. GIẢI NGHĨA Truyện của Trình Di. - Dưới núi có gió, gió gặp núi mà lộn lại, các vật đều tán loạn, cho nên là Tượng “có việc”. Đấng quân tử coi Tượng “cóviệc” để nhức giúp cho dân, gây nuôi đức mình, ở mình nuôi đức, ở thiên hạ thì giúp dân, việc của đấng quân tử, không gi lớn hơn hai điều ấy. Bản nghĩa của Chu Hy. - Dưói núi có gió, các vật hư hỏng mà có việc rồi, mà việc, không gì lớn hơn hai điều ấy (nhức dân nuôi đức) đó là đạo trị mình, trị người. LỜI KINH 初六: 幹⽗之蠱, 有⼦, 考⽆咎, 厲, 終吉.", "Cán phụ chi cổ, hữu tử, khảo vô cữu, lệ, chung cát.", "Hào Sáu Đầu: Cán đáng cuộc cổ của cha, có con, cho khônglỗi, nguy ! Sau chót tốt.", 350, null));
        list.add(new LineJudgment(18, 2, "Cửu Nhị", "象⽈:巧⽗之蠱,意乘考也. Dịch âm. - Tượng viết: Cán mẫu chi cổ, ý thừa khảo dã. Dịch nghĩa. - Lời Tượng nói rằng: Cán đáng sự cổ của cha, ý vâng cha vậy. GIẢI NGHĨATruyện của Trình Di. - Cái đạo con cán đáng sự cổ của cha, là do ý mình vâng nhận công việc của cha, cho nên đối với việc đó bằng cách cung kính, để đặt cha vào chỗ không lỗi, thường thường mang lòng lo sợ gắng gỏi, thì sau chót được tốt, hết lòng thành với việc của cha, đó là đạo tốt. LỜI KINH 初九: 官有渝, 貞吉, 出⾨交有功.", "Cán mẫu chi cổ, bất khả trinh. Dịch âm. -", "Hào Chín Hai: Cán đáng sự cổ của mẹ, không thể trinh.", 352, null));
        list.add(new LineJudgment(18, 3, "Cửu Tam", "象⽈: 官有渝, 從正吉也, 出⾨交有功, 不失也. Dịch âm. - Tượng viết: Cán mẫu chi cổ, đắc trưng đạo dã. Dịch ngỉua. - Lời Tượng nói rằng: Cán đáng sự cổ của mẹ, được trung đạo vậy. GIẢI NGHĨA Truyện của Trình Di. - Được trung đạo mà không quá cứng, đó là kẻ cán đáng sự cổ của mẹ rất khéo. LỜI KINH 九三:乾⽗之蠱,⼩有悔,無⼤咎.", "Cán phụ chi cổ, tiểu hữu hối, vô đại cữu.", "Hào Chín Ba: Cán đáng sự cổ của cha, hơi có ăn năn, không có lỗi lớn.", 353, null));
        list.add(new LineJudgment(18, 4, "Lục Tứ", "象⽈:乾⽗之蠱,終無咎也. Dịch âm. - Tượng viết: Cán phụ chi cổ, chung vô cữu dã. Dịch nghĩa. - Lời Tượng nói rằng: Cán đáng sự cổ của cha, trọn không lỗi vậy. GIẢI NGHĨA Truyện của Trình Di. - Lấy tài hào Ba, cán đáng sự cổ của cha, tuy hơi có ăn năn, rút lại, không có lỗi lớn. Bởi vì nó có đức tính cương đoán, có thể cán đáng, không mất sự chính đính, mà có nhún thuận, vì vậy, sau chót không lỗi. LỜI KINH 六四:裕⽗之盎,往⾒吝.", "Dụ phụ chi cổ, vãng kiến lận.", "Hào Sáu Tư: Rộng rãi với sự cổ của cha, đi thấy tiếc.", 354, null));
        list.add(new LineJudgment(18, 5, "Lục Ngũ", "象⽈:裕⽗之蠱,往未得也. Dịch âm. - Tượng viết: Dụ phụ chi cổ, vảng vị đắc dã. Dịch nghĩa. - Lời Tượng nói rằng: Rộng rãi với sự cổ của cha, đi chưa được vậy. GIẢI NGHĨA Truyện của Trình Di. - Lấy tài, hào Tư, giữ mực thường, ở thì rộng rãi, thì có thể được, muốn có thửa đi, thì chưa được. LỜI KINH 六五:乾⽗之蠱,⽤誊.", "Cán phụ chi cổ, dụng dự.", "Hào Sáu Năm: Cán đáng sự cổ của cha, dùng nhen.", 355, null));
        list.add(new LineJudgment(18, 6, "Thượng Cửu", "象⽈:乾⽗⽤参,乘以德也. Dịch âm. - Tượng viết: Cán phụ dụng dự, thừa dĩ đức dã. Dịch nghĩa. - Lời Tượng nói rằng: Cán đáng cho cha, dùng vâng lây đức vậy. GIẢI NGHĨA Truyện của Trình Di. - Cán đáng sự cổ cho cha, mà được có tiếng khen tốt, là vì người hiền ở dưới vâng giúp cha mình bằng đức cương trung. LỜI KINH 上九:不事王侯,⾼尚其事.", "Bất sự vương hầu, cao thượng kỳ sự.", "Hào Chín Trên: Chẳng thờ tước vương tước hầu, cao nâng thửa việc.", 356, null));

        // Que 19 (LÂM)
        list.add(new LineJudgment(19, 1, "Sơ Cửu", "初九:咸臨,貞吉.", "Hàm lâm, trình cát", "Hào Chín Đầu: Đều tới, chính tốt.", 362, null));
        list.add(new LineJudgment(19, 2, "Cửu Nhị", "象⽈:咸臨貞吉,志⾏正也. Dịch âm. - Tượng viết: Hàm lâm trinh cát, chí hành chính dã. Dịch nghĩa. - Lời Tượng nói rằng: Đều tới chính tốt, chí ở làm sự chính đính vậy. GIẢI NGHĨA Truyện của Trình Di. - Bảo là “trinh cát” vì chí hào Hai ở sự làm điều chính đính. Là hào Chín ở ngôi Dương, lại ứng với hào Tư là hào chính đính, đó là chí nó chính đính. LỜI KINH 九⼆: 咸臨, 吉, ⽆不利.", "Hàm lâm, cát, vô bất lợi.", "Hào Chín Hai: Đều tới, tốt, không gi không lợi.", 363, null));
        list.add(new LineJudgment(19, 3, "Lục Tam", "固未易知: “Nhân cố dị tri: Người ta chỉn chưa dễ biết”. Ý của cổ nhân dùng chữ đều như thế. Người đời nay đại để dùng nó đối với chữ 已 (dĩ là dã), cho nên ý nó giống như khác nhau nhưng mà sự thật vẫn không khác nhau. Hào Chín Hai cảm ứng với Hào Năm để tới kẻ dưới, đó là kẻ lấy đức cứng mạnh mà được mục trung, hết lòng thành cảm nhau, không phải thuận theo mệnh của người trên, cho nên tốt mà không gì không lợi. Hào Năm là thể, thuận[4] mà hào Hai là thể đẹp lòng[5] lại là Âm Dương ứng nhau cho nên lời Tượng tỏ rõ là nó không phải bởi sự vui thuận. Bản nghĩa của Chu Hy. - Chưa rõ ý nghĩa ra sao.LỜI KINH 六三: ⽢臨,無攸利,既憂之,無咎.", "Cam Lâm, vô do lợi, ký ưu chi, vô cữu.", "Hào Sáu Ba: Ngọt tới, không thửa lợi, đã lo đó, không lỗi.", 365, null));
        list.add(new LineJudgment(19, 4, "Lục Tứ", "象⽈: ⽢臨,位不當也; 既憂之.咎不⾧也. Dịch âm. - Tượng viết: Cam lâm, vị bất đáng dã; kỳ ưu chi, cửu bất trường dã. Dịch nghĩa. - Lời Tượng nói rằng: Ngọt tới, ngôi không đáng vậy; đã lo đó, lỗi không dài vậy. GIẢI NGHĨA Truyện của Trình Di. - Người Âm nhu, ở chỗ không trung chính, nhằm trênthể dưới, lại cưỡi trên hai hào Dương, đó là ở không đáng ngôi. Đã biết sợ mà lo, thì ắt miễn cưỡng tự đổi, cho nên sự lỗi không dài. LỜI KINH 六四: ⾄臨,無咎.", "Chí lâm, vô cữu.", "Hào Sáu Tư; Rất tới, không lỗi.", 366, null));
        list.add(new LineJudgment(19, 5, "Lục Ngũ", "象⽈: ⾄臨無啓,位當也. Dịch âm. - Tượng viết: Chí lâm vô cữu, vị đáng dã. Dịch nghĩa. - Lời tượng nói rằng: rất tới không lỗi, ngôi đáng vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở ngôi gần vua là được dùng, lấy hào Âm ở ngôi tư là được chỗ chính, ứng nhau với hào Đầu là biết nhún vởi người hiền, sở dĩ không lỗi, vì ngôi đó đáng.LỜI KINH 六五: 知臨,⼤君之宜,吉.", "Trí lâm, đại quân chi nghi, cát!", "Hào Sáu Năm: Khôn tới, sự nên của vua cả, tốt!", 367, null));
        list.add(new LineJudgment(19, 6, "Thượng Lục", "象⽈: ⼤君之宜,⾏終之謂也. Dịch âm. - Tượng viết: Đại quân chi nghi, hành trung chi vị dã. Dịch nghĩa. - Lời Tượng nói rằng: Sự nên của vua cả, nghĩa là làm theo đứcgiữa vậy. GIẢI NGHĨA Truyện của Trình Di. - Vua tôi hợp đạo là lấy khí loại tìm nhau. Hào Năm có đức giữa, cho nên có thể tin dùng người hiền có đức cứng giữa, được sự nên làm của vua cá, mà thành cái công “khôn tới” là bởi làm theo đức giữa của mình. Ông vua với bậc hiền tài, nếu không phải đạo đồng đức, há có thể dùng! LỜI KINH 上六: 敦臨,吉,無咎.", "Đôn lâm, cát, vô cữu.", "Hào Sáu Trên: Dầy tới, tốt, không lỗi.", 368, null));

        // Que 20 (QUÁN)
        list.add(new LineJudgment(20, 1, "Sơ Lục", "初六: 童觀,⼩⼈無咎,君⼦吝.", "Đồng quán, tiểu nhân vô cữu, quân tử lận.", "Hào Sáu Đầu: Trẻ xem, kẻ tiểu nhân không lỗi, đấng quân tử đáng tiếc.", 374, null));
        list.add(new LineJudgment(20, 2, "Lục Nhị", "象⽈: 初六童#,⼩⼈道也. Dịch âm. - Tượng viết: Sơ Lục đồng quan, tiểu nhân đạo dã. Dịch nghĩa. - Lời Tượng nói rằng: Hào Sáu đầu trẻ xem, đạo kẻ tiểu nhân vậy. GIẢI NGHĨA Truyện của Trình Di. - Sự xem không rõ, như trẻ nít, là phận của kẻ tiểu nhân, cho nên nói rằng “tiểu nhân đạo”.LỜI KINH 六⼆: 窥觀,利⼥貞.", "Khuy quan, lợi nữ trinh.", "Hào Sáu Hai: Nhòm xem, lợi về sự trinh của con gái.", 375, null));
        list.add(new LineJudgment(20, 3, "Lục Tam", "象⽈: 窥觀⼥貞,亦可#也. Dịch âm. - Tượng viết: Khuy quan, nữ trinh, diệt khả xú dã. Địch nghĩa. - Lời Tượng nói rằng: Dòm xem, sự trinh của con gái cũng đáng xấu vậy. GIẢI NGHĨATruyện của Trình Di. - Đấng quân tử không thể xem thấy đạo lớn Dương cương trung chính mà chỉ dòm ngó được cái phảng phất của nó, tuy rằng có thể thuận theo, nhưng mà giống với sự trinh của con gái, cũng đáng xấu hổ vậy. Bản nghĩa của Chu Hy. - Ở đàn ông là xấu. LỜI KINH 六三: 觀我⽣,進退.", "Quan ngã sinh tiến thoái.", "Hào Sáu Ba: Xem ta sinh tiến lui.", 376, null));
        list.add(new LineJudgment(20, 4, "Lục Tứ", "象⽈: 觀我⽣,進退,未失道也.Dịch âm. - Tượng viết: Quan ngã sinh tiến thoái, vị thất đạo dã. Dịch nghĩa. - Lời Tượng nói rằng: Xem ta sinh tiến lui, chưa mất đạo vậy. GIẢI NGHĨA Truyện của Trình Di. - Xem cái của mình sinh ra mà tiến lui, cho thuận với sự nên phải, cho nên chưa đến mất đạo. LỜI KINH 六四: 觀國之#,利⽤賓于王.", "Quạn quốc chi quang, lợi dụng tân vu vương.", "Hào Sáu Tư: Xem sự sáng láng của nước, lợi dụng làm khách chưng vua.", 377, null));
        list.add(new LineJudgment(20, 5, "Cửu Ngũ", "象⽈: 觀國之#,尚賓也. Dịch âm. - Tượng viết: Quan quốc chi quang, thượng tân dã. Dịch nghĩa. - Lời Tượng nói rằng: Xem sự sáng của nước, chuộng làm khách vậy. GIẢI NGHĨA Truyện của Trình Di. - Đã xem thấy sự thịnh đức sáng đẹp của nước, cổ nhân cho là một cuộc gặp gỡ phi thường, cho nên chí muốn tiến lên sân triều nhà vua, để thực hành cái đạo của mình, cho nên nói rằng: “Xem sự sáng của nước, chuộng làm khách vậy”. Thượng là chuộng chí, chí ý của nó thích muốn làm khách ở sân triều nhà vua. LỜI KINH 九五: 觀我⽣,君⼦無咎.", "Quan ngã sinh, quân tử vô cữu.", "Hào Chín Năm: Xem ta sinh, quân tử, không lỗi.", 378, null));
        list.add(new LineJudgment(20, 6, "Thượng Cửu", "象⽈: 觀我⽣,觀民也. Dịch âm. - Tượng viết: Quan ngã sinh, quan dân dã. Dịch nghĩa. - Tượng viết: Xem ta sinh, là xem dân vậy. GIẢI NGHĨA Truyện của Trình Di. - Ta sinh là cái do mình mà ra, ông vua muốn xem sự thi vi của mình có phải hay không, nên xem ở dân, tục dân hay, là chính hóa hay, Vương Bật bảo: “Xem dân để xét cái đạo của mình”, là phải đó. Bản nghĩa của Chu Hy. - Đây là đấng Phu Tử lấy nghĩa mà nói, tỏ rằng ông vua muốn đem cái của mình đã làm, không những về sự được hỏng trong một thân mình, lại nên xem cả đức dân phải chăng thế nào, để tự tỉnh xét. LỜI KINH 上九: 觀其⽣,君⼦無咎.", "Quan kỳ sinh, quân tử vô cữu.", "Hào Chín Trên: Xem thửa sinh, quân tử không lỗi.GIẢI NGHĨA Truyện của Trình Di. - Hào Chín Trên lấy đức Dương cương, ở trên, bị kẻ dưới thửa xem mà không đáng ngôi, đó là những đấng hiền nhân quân tử không ở ngôi mà đạo đức bị người thiên hạ xem ngửa. Vậy “xem thửa sinh” là xem cái thửa sinh của mình, chỉ về những cái do mình mà ra, tác là đức nghiệp hạnh nghĩa. Đã bị thiên hạ xem ngửa, cho nên tự xem những cái thửa sinh, nếu như đều là quân tử thì không có lỗi, ví mà chưa được quân tử, thì còn lấy gì để cho người ta ngửa xem bắt chước, đó là lỗi vậy. Bản nghĩa của Chu Hy. - Hào Chín Trên là hào Dương cương ở bậc trên ngôi tôn, tuy chẳng đương vào công việc, mà cũng bị kẻ dưới thửa xem, cho nên lời răn của nó cũng giống như Hào Chín Năm, chỉ đổi chữ # (ngã) ra chữ # (kỳ), hơi có chủ khách khác nhau mà thôi.", 379, null));

        // Que 21 (PHỆ HẠP)
        list.add(new LineJudgment(21, 1, "Sơ Cửu", "象⽈: 雷電噬嗔,先王以明罰敕去Dịch âm. - Tượng viết: Lôi điện Phệ hạp, tiên vương dĩ minh phạt sắc pháp. Dịch nghĩa. - Lời Tượng nói rằng: Sấm chớp là quẻ Phệ hạp, đấng Tiên vương coi đó để tỏ phạt truyền phép. GIẢI NGHĨA Truyện của Trình Di. - Lời Tượng không đặt đảo, chỗ này ngờ là lộn nhau. Sấm chớp là vật chờ nhau cùng hiện, cũng có tượng hợp. Chớp sáng mà sấm oai, đấng Tiên vương coi tượng sấm chớp, bắt chước cái sáng cái oai của nó để tỏ hình phạt và sức pháp lệnh. Pháp là tỏ rõ sự lý mà đặt ra cách ngăn ngừa. Bản nghĩa của Chu Hy. - Hai chữ “lôi điện” nên đổi ra làm “điện lôi”. LỜI KINH #九: 履校滅趾,無咎.", "Lý hiệu, diệt chỉ, vô cữu.", "Hào Chín Đầu; Xéo xiềng, đứt ngón chân, không lỗi.", 386, null));
        list.add(new LineJudgment(21, 2, "Lục Nhị", "象⽈: 履消滅趾,不⾏也. Dịch âm. - Tượng viết: Lý hiệu, diệt chỉ, bất hành dã. Dịch nghĩa. - Lời Tượng nói rằng: Xéo xiềng, đứt ngón chân, không đi vậy. GIẢI NGHĨA Truyện của Trình Di. - Xéo vào xiềng mà bị đứt đau ngón chân, thì biết răn sợ mà không gây lớn điều ác, cho nên nói là không đi. Người đời xưa đặt ra hình phạt, có tội nhỏ thì xiềng ngón chân, đó là nghĩa ngăn cấm sự đi, không cho tiến về đường ác. Bán nghĩa của Chu Hy. - Đứt ngón chân lại có tượng “không tiến về đường ác”. LỜI KINH 六⼆: 噬廣,滅⿐,無咎.", "Phệ phu, diệt ty, vô cữu.", "Hào Sáu Hai: Cắn da, dứt mũi, không lỗi.", 387, null));
        list.add(new LineJudgment(21, 3, "Lục Tam", "象⽈: 噬膚滅⿐,乘剛也. Dịch âm. - Tượng viết: Phệ phu diệt ty, thừa cương dã. Dịch nghĩa. - Lời Tượng nói rằng: cắn da cụt mũi, vì cưỡi cứng vậy. GIẢI NGHĨA Truyện của Trình Di. - Sâu đến ngập mũi, là vì cưỡi lên kẻ cứng. Cưỡi lên kẻ cứng tức là dụng hình với người cương trường, không thể không nghiêm. Nghiêm thì được sự thích nghỉ, đó là trung đạo. LỜI KINH 六三: #臘⾁,遇毒,⼩吝,無咎.", "Phệ tích nhục, ngộ độc tiểu lận, vô cữu.", "Hào Sáu Ba: cắn mắm khô, gặp độc, hơi tiếc, không lỗi.", 388, null));
        list.add(new LineJudgment(21, 4, "Cửu Tứ", "象⽈: 遇毒,位不當也. Dịch âm. - Tượng viết: Ngộ độc, vị bất đáng dã. Dịch nghĩa. - Lời Tượng nói rằng: Gặp độc, ngôi không đáng vậy. GIẢI NGHĨA Truyện của Trình Di. - Hào Sáu Ba là chất Âm, ở ngôi Dương, tức là ngôi ở không đáng. Bởi nó tự xử không đáng, cho nên những kẻ mà nó vô hình phạt khó phục mà lại làm độc cho nó. LỜI KINH 九四:#秭,得⾦⽮,利艱貞,吉.", "Phệ can tỷ, đắc kim thỉ, lợi gian trình, cát!", "Hào Chín Tư: Cắn chạo khô, được tên vàng, lợi về khó nhọc, chính bền tốt.", 389, null));
        list.add(new LineJudgment(21, 5, "Lục Ngũ", "象⽈: 利艱貞吉,未光也. Dịch âm. - Tượng viết: Lợi gian trinh, cát, vị quang dã. Dịch nghĩa. - Lời Tượng nói rằng: Lợi về khó nhọc, chính bền tốt, là chưa sáng vậy. GIẢI NGHĨATruyện của Trình Di. - Phàm những chỗ nói “chưa sáng” đều là đạo chưa sáng lớn. Răn bằng câu “lợi về khó nhọc chính bền”, đó là chỗ nó không đủ. Bồi vì nó không được trung chính, cho nên như thế. LỜI KINH 六五: 禮乾⾁,得黄⾦厲,無咎.", "Phệ can nhục, đắc hoàng kim, trinh lệ, vô cữu.", "Hào Sáu Năm: Cắn thịt khô, được vàng vàng, chính bền, lo sợ, không lỗi.", 391, null));
        list.add(new LineJudgment(21, 6, "Thượng Cửu", "象⽈: 專属無咎,得當也. Dịch âm. - Tượng viết: Trinh lệ vô cữu, đắc đáng dã. Dịch nghĩa. - Lời Tượng nói rằng: Chính bền, lo sợ, không lỗi, vì được đáng vậy. GIẢI NGHĨA Truyện của Trình Di. - Sở dĩ có thể không lỗi, là vì việc của nó làm xứng đáng. Gọi là “đáng” tức là ngôi giữa, dùng kẻ cứng, mà biết giữ đường chính đính, lo sự hiểm nghèo. LỜI KINH 上#: 何校,滅⽿,凶.", "Hạ hiệu, diệt nhĩ, hung!", "Hào Chín trên: Đội xiềng, đứt tai, hung!", 392, null));

        // Que 22 (BÍ)
        list.add(new LineJudgment(22, 1, "Sơ Cửu", "初九:贲其址,舍⾞⽽徒,", "Bí kỳ chỉ, xả xa nhi đồ.", "Hào Chín Đầu: Trang sức thửa ngón chân, bỏ xe mà đi không.", 399, null));
        list.add(new LineJudgment(22, 2, "Lục Nhị", "象⽈:舍⾞⽽徒,義弗乘也. Dịch âm. - Tượng viết: Xả xa nhi đồ, nghĩa phất thừa dã. Dịch nghĩa. - Lời Tượng nói rằng: Bỏ xe mà đi không, nghĩa không nên cưỡi vậy. GIẢI NGHĨA Truyện của Trình Di. - Bỏ xe mà đi chân không, là vì, với nghĩa, không có thể cưỡi. Hào Đầu ứng với hào Tư là chính đáng; theo hào Hai là khôngchính đáng; ở gần, nó bỏ hào Hai là chỗ dễ mà theo hào Tư là chỗ khó, tức là bỏ xe mà đi chân không. Sự trang sức của đấng quân tử, chỉ cốt giữ nghĩa của mình mà thôi. Bản nghĩa của Chu Hy. - Sự lấy sự bỏ của đấng quán tử, quyết định bằng nghĩa mà thôi. LỜI KINH 六⼆ : 贲其須.", "Bí kỳ tu.", "Hào Sáu Hai: Trang sức cái râu của mình.", 401, null));
        list.add(new LineJudgment(22, 3, "Cửu Tam", "象⽈:贲其須,與上興也. Dịch âm. - Tượng viết: Bí kỳ tu, dữ thượng hưng dã. Dịch nghĩa. - Lời Tượng nói rằng: Trang sức cái râu của mình, cùng trên dấy vậy. GIẢI NGHĨA Truyện của Trình Di. - Lấy cái râu làm Tượng tức là bảo nó cùng với hào Trên cùng dấy lên vậy. Theo người trên mà động, động đậy hay dừng đậu, quan hệ ở cái nó bám vào, cũng như tô điểm cho vật nào, chỉ nhân chất của vật ấy mà trang sức thêm thiện hay ác là ở cái chất của nó. LỜI KINH 九三:贲如,濡如,永貞吉.", "Bí như, nhu như, vĩnh trinh, cát.", "Hào Chín Ba: Rõ ràng vậy,bóng mượt vậy; mãi mãi chính bền tốc.", 402, null));
        list.add(new LineJudgment(22, 4, "Lục Tứ", "象⽈: 永貞之吉, 終莫之陵也. Dịch âm. - Tượng viết: Vĩnh trinh chi cát, chung mạc chi lăng dã. Dịch nghĩa. - Lời Tượng nói rằng: Lâu dài chính bền mà tốt, là vì không gì lấn nó. GIẢI NGHĨA Truyện của Trình Di. - Trang sức mà không thường thường và không đính chính, người ta sẽ lấn nhờn, cho nên nói rằng có thể lâudài chính đính thì tốt. Sự trang sức của nó đá thường thường và chính đính, ai lấn được nó? LỜI KINH 六四:贲如,播如,⽩⾺翰如,匪底,婚媾.", "Bí như, phan như, bạch mâ hản nhưĩ Phì khấu, hôn câu.", "Hào Sáu Tư: Rỡ ràng vậy, phơ phơ vậy, ngựa trắng có cánh vậy. Chẳng phải giặc, dâu gia.GIẢI NGHĨA Truyện của Trình Di. - Hào Tư với hào Đầu là chính ứng, trang sức cho nhau, đáng lẽ có vẻ rỡ ràng. Vì bị hào ngăn cách cho nên không được trang sức cho nhau mà thành vẻ phơ phơ. Phơ phơ là trắng, tức là chưa được rỡ ràng. Ngựa là vật ở dưới mà động, chưa được rỡ ràng, cho nên nói là “ngựa trắng”; chí theo chính ứng của nó như bay, cho nên nói rằng “dường có cánh vậy’; chẳng bị hào Chín Ba là kẻ giặc thù ngăn cách, thì cuộc dâu gia sẽ được thỏa tình thân nhau. Cái mà mình cưỡi và động ở dưới là tượng con ngựa. Hào Đầu với hào Tư là chính ứng, sau chót ắt được thân nhau, có điều lúc đầu bị nó ngăn cách mà thôi. Bản nghĩa của Chu Hy. - Phơ phơ là trắng, ngựa là con vật người ta cưỡi lên, người trắng thì ngựa cũng trắng. Hào Tư với hào Đầu là kẻ trang sức cho nhau, nhưng bị hào Chín Ba ngăn cách mà không được thỏa, cho nên có vẻ phơ phơ, mà chí đi tìm của nó kíp như cánh bay. Song hào Chín Ba là bậc cương chính, không phải kẻ làm giặc, chỉ là tìm người dâu gia mà thôi, cho nên tượng nó như thế. Lời bàn của Tiên Nho. - Vương Đại Bảo nói rằng: Phơ phơ là vẻ tóc bạc. Hào mềm trang sức hào mềm, Âm thịnh Dương suy, là tượng phơ phơ.", 403, null));
        list.add(new LineJudgment(22, 5, "Lục Ngũ", "六五:贲于丘囷,系$更吝,终吉.", "Bí vu khâu viênt thúc bạch tiên tiên, lận chung cát.", "Hào Sáu Năm: Trang sức ở gò vườn, bó lụa mỏng hẹp, đáng tiếc, sau chót tốt.", 405, null));
        list.add(new LineJudgment(22, 6, "Thượng Cửu", "象⽈:六五之吉,有喜也. Dịch âm. - Tượng viết: Lạc ngũ chi cắt, hữu hỷ dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái tốt của hào Sáu Năm, có sự mừng vậy. GIẢI NGHĨA Truyện của Trình Di. - Biết theo người để làm cho thành công cuộc trang sức mà hưởng sự tốt đẹp của nó, thế là có sự mừng. LỜI KINH 上九:⽩贵,無咎.", "Bạch bi, vô cữu.", "Hào Chín Trên: Trang sức bằng màu trắng, không lỗi.", 406, null));

        // Que 23 (BÁC)
        list.add(new LineJudgment(23, 1, "Sơ Lục", "初六:剝床以⾜,蔑貞凶.", "Bác sàng dĩ túc, miệt trinh, hung.", "Hào Sáu Đầu: Đẽo giường bằng[5] chân, không trinh, hung.", 411, null));
        list.add(new LineJudgment(23, 2, "Lục Nhị", "象⽈:#床以⾜,以滅下也. Dịch âm. - Tượng viết: Bác sàng dĩ túc, dĩ diệt hạ dã. Dịch nghĩa. - Lời Tượng nói rằng: Đẽo giường bằng chân, vì dứt dưới vậy.GIẢI NGHĨA Truyện của Trình Di. - Dùng chân giường làm tượng, là lấy vẻ nghĩa Âm lấn ngập Dương ở dưới vậy. “Diệt” nghĩa là ngập, tức là lâíi ngập chính đạo, từ dưới trở lên. LỜI KINH 六⼆:剝床以辨,蔑負凶.", "Bác sàng dĩ biện, miệt trinh hung.", "Hào Sáu Hai: Đẽo giường bằng bễ, chẳng trinh, hung!", 412, null));
        list.add(new LineJudgment(23, 3, "Lục Tam", "象⽈:剝床以辨,未有與也 . Dịch âm. - Tượng viết: Bác sàng dĩ biện, vị hữu dữ dã. Dịch nghĩa. - Lời Tượng nói rằng: Đẽo giường bằng bễ, chưa có “cùng” vậy. GIẢI NGHĨA Truyện của Trình Di. - Âm lấn đẽo Dương, được càng thịnh và đến đẽo bễ,là vì Dương không có kẻ ứng cùng. Tiểu nhân lấn đẽo quân tử, nếu quân tử cókẻ “cùng với”,thì có thể thắng tiểu nhân, tiểu nhân không làm hại được, chỉ vì không kẻ cùng với, cho nên bị dứt mà hung. Đương lúc tiêu bác mà không có phe cánh, tự tồn sao được? Nói “chưa có kẻ cùng với” tỏ rằng: Sự đẽo chưa thịnh, có kẻ cùng với, còn có thề thắng, cái ý dạy bảo người ta sâu lắm. Bản nghĩa của Chu Hy. - Đây nói sự đẽo chưa thịnh lắm. LỜI KINH 六三:剝之,無咎.", "Bác chi, vô cữu.", "Hào Sáu Ba: Đẽo đó, không lỗi.", 413, null));
        list.add(new LineJudgment(23, 4, "Lục Tứ", "象⽈;剝之無咎,失天下也. Dịch âm. - Tượng viết: Bác chi vô cữu, thất thượng hạ dã. Dịch nghĩa. - Lời Tượng nói rằng: Đẽo đó, không lỗi, mất trên dưới vậy. GIẢI NGHĨATruyện của Trình Di. - Hào Ba ở cuộc đẽo mà không có lỗi, vi chỗ nó ở không giống như các hào Âm trên dưới, ấy là mất kẻ đồng loại. Với cách ở cuộc đẽo, như thế là không lỗi. Bản nghĩa của Chu Hy. - Trên dưới chỉ về bốn hào Âm. LỜI KINH. 六四:剝床以廣,凶.", "Bác sàng dĩ phu, hung!", "Hào Sáu Tư: Đẽo giường bằng da, hung!", 414, null));
        list.add(new LineJudgment(23, 5, "Lục Ngũ", "象⽈:剝床以膚,切近災也. Dịch âm. - Tựợng viết: Bác sàng dĩ phu, thiết cận tai dã. Dịch nghĩa. - Lời Tượng nói rằng: Đẽo giường bằng da, sát gần vạ vậy. GIẢI NGHĨA Truyện của Trình Di. - Hào Năm là ngôi vua, sự đẽo đã đến hào Tư, ở ngườita thì là đẽo đến da rồi. Đẽo đến da, thân sắp sửa mất,thế là sát gần tai vạ. LỜI KINH 六無:貫⿂以宮⼈⿓,無a n.", "Quán ngư dĩ cung nhân sủng, vô bất lợi.", "Hào Sáu Năm: Xâu cá; lấy cung nhân được yên, không gì không lợi.", 415, null));
        list.add(new LineJudgment(23, 6, "Thượng Cửu", "象⽈:以宮⼈寵,終無憂也. Dịch âm. - Tượng viết: Dĩ cung nhân sủng, chung vô vưu dã.Dịch nghĩa. - Lời Tượng nói rằng: Lấy cung nhân được yêu, sau chót không có lỗi vậy. GIẢI NGHĨA Truyện của Trình Di. - Các hào Âm tiêu đẽo hào Dương đều nổi cùng cực, hào Sáu Năm nếu biết đứng đầu dắt các hào Âm đứng đầu thuận theo thứ tự, lại được hào Dương yêu đương, thì sau chót không có tội lỗi. Về chỗ cuộc đẽo sắp hết, lại phát ra nghĩa đó, cái ý khuyên người dời sang đường thiện của thánh nhân thâm thiết đến tột bậc vậy. LỜI KINH 上九:碩果不⾷,君⼦得輿,⼩⼈剥启.", "Thạc quả bất thực, quân tử đắc dư, tiểu nhân bác lư.", "Hào Chín Trên: Trái lớn không ăn, đấng quân tử được xe, kẻ tiểu nhân đẽo nhà.", 416, null));

        // Que 24 (PHỤC)
        list.add(new LineJudgment(24, 1, "Sơ Cửu", "初九:不遠復, 無祗悔, 元吉.", "Bất viễn phục, vô chỉ hối, nguyên cát", "Hào Chín Đầu: Chẳng xa trở lại, không đến ăn năn, cả tốt.", 424, null));
        list.add(new LineJudgment(24, 2, "Lục Nhị", "氐(chi) nghĩa là đến. Lỗi mất chưa xa, đã biết trở lại đường thiện, không đến phải ăn năn, đó là cái đạo cả thiện mà tốt, cho nên Tượng, Chiêm của nó như thế. LỜI KINH初九:不遠復,無祗悔,元吉. Dịch âm. - Tượng viết: Bất viễn chi phục, dĩ tu thân dã. Dịch nghĩa. - Lời Tượng nói rằng: Sự trở lại của việc chẳng xa, để sửa mình vậy. GIẢI NGHĨA Truyện của Trình Di. - Chẳng xa mà trở lại, tức là cái đạo mà đấng quân tử sở dĩ sửa mình. Cái đạo học hỏi, không có gì khác, chỉ hễ biết điều, không phải của mình thì mau đổi đi, để theo điều phải mà thôi. LỜI KINH 六⼆:休復,吉.", "Hưu phục cát!", "Hào Sáu Hai: Đẹp sự trở lại, tốt!", 425, null));
        list.add(new LineJudgment(24, 3, "Lục Tam", "象⽈:休復之吉,以下仁也Dịch âm. - Tượng viết: Hưu phục chi cắt, dĩ hạ nhân dã. Dịch nghĩa. - Lời Tượng nói rằng: Đẹp sự trở lại mà tốt, vì biết lớn với kẻ nhân vậy. GIẢI NGHĨA Truyện của Trình Di. - Là sự trở lại đẹp đẽ mà tốt, vì nó biết nhún với kẻ nhân. Nhân là đức chung của thiên hạ, là gốc của điều thiện, hào Đầu trở lại điều nhân, hào Hai biết thân và nhún với nó, cho nên mới tốt. LỜI KINH 六三:頻復, 厲, 無咎.", "Tần phục lệ, vô cữu. Dỉch nghĩa. -", "Hào Sáu Ba: Luôn luôn trở lại, nguy! Không lỗi.", 426, null));
        list.add(new LineJudgment(24, 4, "Lục Tứ", "象⽈:頻復之属,義無咎也. Dịch âm. - Tượng viết: Tần phục chi lệ, nghĩa vô cữu dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái nguy của sự luôn luôn trở lại, nghĩa không lỗi vậy. GIẢI NGHĨA Truyện của Trình Di. - Luôn luôn trở lại, luôn luôn lỗi mất, tuy là nguy dữ, nhưng theo nghĩa trở lại điều thiện thì không có lỗi. LỜI KINH 六四:中⾏獨後.", "Trung hành độc phục.", "Hào Sáu Tư: Đi giữa một mình trở lại.", 427, null));
        list.add(new LineJudgment(24, 5, "Lục Ngũ", "象⽈:中⾏獨復,以從道也. Dịch âm. - Tượng viết: Trung hành độc phục, dĩ tòng đạo dã. Dịch nghĩa. - Lời Tượng nói rằng: Đi giữa, một mình trở lại, để theo đạo vậy. GIẢI NGHĨA Truyện của Trình Di. - Khen có một mình trở lại, vì nó biết theo đạo thiện, thiện của đấng quân tử Dương cương vậy. LỜI KINH 六五:敦復,無悔.", "Đôn phục, vô hối..", "Hào Sáu Năm: Dốc lòng về sự trở lại,không phải ăn năn.", 428, null));
        list.add(new LineJudgment(24, 6, "Thượng Lục", "象⽈:敦復無悔,中以⾃考也. Dịch âm. - Tượng viết: Đôn phục vô hối, trung dĩ tự khảo dã. Dịch nghĩa. - Lời Tượng nói rằng: Dốc lòng về sự trở lại, dùng đạo trung để tự nên vậy. GIẢI NGHĨA Truyện của Trình Di. - Tức là dùng đạo “trung”,để tự làm nên cho mình. Hào Năm lấy chất Âm đương ngôi tôn, ở chỗ giữa mà thể theo sự thuận, biết dốc lòng dùng đạo trung để làm nên cho minh, thì có thể không phải ăn năn. Tự làm nên, nghĩa là làm nên cái đức trung thuận. Bản nghĩa của Chu Hy. - Chữ “khảo” nghĩa là “nên”. LỜI KINH 上六:年復,巧,有災眚.⽤#師,終有⼤琴,以其國君;凶Ẵ⼿⼗年,不可征.", "Mê phục, hung, hữu tai sảnh, dụng hành sư, chung hữu đại bại; dĩ kỳ quốc quân,hung, chí vu thập niên, bất khắc chính.", "Hào Sáu Trên: Lú lấp sự trở lại, hung! Có vạ tội, dùng để trẩy quân, sau chót có thua lớn; tới cả vua nước đó, đến chừng mười năm, không thể đi.GIẢI NGHĨA Truyện của Trình Di. - Đây là kẻ lấy chất Âm nhu ở vào chót cuộc trở lại, rút lại vẫn lú lấp mà không trở lại. Lú lấp mà không trở lại,đủ biết là hung. Có vạ tội: vạ là vạ trời, tự ngoài đến, tội lối mình, do mình làm ra. Đã lú lấp không biết trở lại đường, thiện, ở mình thì động đâu là lầm lỗi đấy, tai họa cũng tự bên ngoài mà đến, nghĩa là cũng bởi tự mình vời đến. Lú lấp đường lối mà không trở lại, không thể thi thố việc gì được cả, dùng để trẩy quân, thì rút lại phải có thua lớn, đem mà trị nước, thì là điềm hung của ông vua. Mười năm là chỗ chót của số, đến mười năm không thể đi, nghĩa là cùng chót không thể đi đâu. Đã lú lấp đường lối, thì bao giờ mà đi được? Bản nghĩa của Chu Hy. – Lấy chất Âm mềm ở chót cuộc trở lại, đó là tượng cùng chót vẫn lú lấp không biết trở lại, cho nên lời chiêm như thế, chữ 以(dĩ) cũng như chữ 及(cập là kịp). Lời bàn của Tiên Nho. - Có người hỏi: Y Xuyên nói “tai tự ngoài đến, sảnh tự trong ra” có phải hay không? Chu tử đáp rằng: Xem ra hai thứ cũng một hơi không giống nhau mà thôi. Tai là cái ngẫu nhiên sinh ra ở kia, sảnh là do sự lầm lỗi mà đến thế. Kinh Thư nói,眚災碑赦 (sảnh tai tứ xá), sách Xuân thu nói 四⼤眚 (tứ đại sảnh) đều vì sự lỗi lầm mà tha cả. Hồ Vân Phong nói rằng: Thể mẹ[3] mà ở trên thể trên, đó là kẻ lú lấp trước. Lú lấp chẳng những chỉ hung, lại có vạ lớn, tội lớn, dùng để trẩy quân, cùng chót phải có thua to, kịp cả vua nước hung. Đến mười năm, cùng chót không thể đi đâu đó là hết sức nói việc lú lấp sự trở lại là việc không nên. “Lú lấp sự trở với “chẳng xa trở lại” trái nhau, hào Đầu chẳng xa mà trở lại lú lấp thì xa mà không trở lại: “dốc lòng trở về sự trở lại” với “luôn luôn trở lạin trái nhau, ”dốc” là không lay chuyển thay đổi, “luôn luôn thì thay đổi liền liền. “Một mình trở lại” với “đẹp sự trở lại” giống nhau, “đẹp” thì liền với hào Đầu, “một mình” thì ứng với hào Đầu. “Mười năm không thể đi” cũng trái lại với “bảy ngày lại trở lại”. Kiền nguyên là mười, Khôn nguyên là một, sốÂm cùng tận ở “Sáu,,mà “bảy” lại là chỗ bắt đầu của Kiền; số Dương cùng tận ở “chín” mà “mười” thì là chỗ cuối chót của Khôn. Cho nên, hễ nói “mười năm” là tượng chót Khôn, quẻ Chuân “mười năm mới đặt tên chữ”", 429, null));

        // Que 25 (VÔ VỌNG)
        list.add(new LineJudgment(25, 1, "Sơ Cửu", "初九:無妄,往吉.", "Vô vọng vãng cát", "Hào Chín Đầu: Không càn, đi tốt.", 437, null));
        list.add(new LineJudgment(25, 2, "Lục Nhị", "象⽈:無妄之往,得志今. Dịch âm. - Tượng viết: Vô vọng, chi vãng, đắc chí dã. Dịch nghĩa. - Lời Tượng nói rằng: Sự đi của đức không càn, là đắc chí vậy. GIẢI NGHĨA Truyện của Trình Di. - Lấy đức không cànt không chỗ nào mà không được thỏa chí mình. Bởi vì sự thành thật đối với các vật, không vật nào mà khôngcảm động, dùng nó sửa mình thì ngay, dùng nó làm việc thì việc được hợp lẽ, dùng nó trị người, thì người ta cảm mà hóa theo, không đi đâu mà không đắc chí. LỜI KINH 夫⼆:不耕獲,不菌畲, 則利有攸終", "Bất canh hoạch, bất tri dư, tắc lợi hữu du vãng.,", "Hào Sáu Hai: Chẳng cây, gặt; chẳng ngả, ngấu[4] thì lợi có thửa đi.", 438, null));
        list.add(new LineJudgment(25, 3, "Lục Tam", "富（phú) này cũng như chữ富 (phú) trong câu ⾮富天下(phi phú thiên hạ: chẳng phải là muốn được cả thiên hạ làm giàu), ý nói “không phải là vì tính lợi mà làm”. LỜI KINH 六三:無妄之災,或繫之⽜,⾏⼈之得,⼈之災.", "Vô vọng chi tai, hoặc hệ chi ngưu, hành nhân chi đắc, ấp nhân chi tai.", "Hào Sáu Ba: Cái hại của sự không càn, hoặc buộc con trâu, kẻ đi đường mà được, người ấp bị hại.", 440, null));
        list.add(new LineJudgment(25, 4, "Cửu Tứ", "象⽈:⾏⼈得⽜,⾢⼈災也. Dịch âm. - Tượng viết: Hành nhân đắc ngưu, ấp nhân tai dã. Dịch nghĩa. - Lời Tượng nói rằng: Người đi đường được trâu, là hại của người ấy vậy. GIẢI NGHĨA Truyện của Trình Di. - Người đi đường được trâu,tức là cái vạ của người trong ấp, có kẻ được thì cò kẻ mất, sao đủ cho là sự được? LỜI KINH 九四: 可貞, ⽆咎", "Khả trinh, vô cữu", "Hào Chín Tư: Khả trinh, không lỗi.", 441, null));
        list.add(new LineJudgment(25, 5, "Cửu Ngũ", "象⽈: 可貞⽆咎, 固有之也. Dịch âm. - Tượng viết: Khả trinh vô cữu, cố hữu chi dã. Dich nghĩa. - Lời Tượng nói rằng: Khá trinh không lỗi, cố giữ đó vậy. GIẢI NGHĨA Truyện của Trình Di. - Chính bền giữ đó, thì không có lỗi. Bản nghĩa của Chu Hy. – Chữ 有(hữu) đây cũng là chữ 守(thủ) là giữ. LỜI KINH 象⽈: 可貞⽆咎, 固有之也.", "Vô vọng chi tật, vật dược, hữu hỷ.", "Hào Chín Năm: Cái tật không càn, đừng thuốc, có mừng.", 442, null));
        list.add(new LineJudgment(25, 6, "Thượng Cửu", "参⽈:無妄之蔡,不可詩也 Dịch âm. - Tượng viết: Vô Vọng chi dược, bất khả thí dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái thuốc không càn, chẳng khá thử vậy. GIẢI NGHĨA Truyện của Trình Di. - Người ta có sự càn bậy lẽ phải sửa đổi. Đã không càn rồi, lại còn lấy thuốc để chữa, thế là càn có thể dùng chăng? Cho nên nói là “chẳng khá thử”’. Thử là dùng tạm, cũng như nói “nếm một ít”. Bản nghĩa của Chu Hy. - Đã là không càn mà lại thuốc men thì lại là càn mà sinh ra tật, Thử là hãy nếm một ít. LỜI KINH 上九:無妄⾏,有眚,無攸利.", "Vô Vọng hành, hữu sảnh, vô du lợi.", "Hào Chín Trên: Không càn mà đi, có tội, không thửa lợi.,", 443, null));

        // Que 26 (ĐẠI SÚC)
        list.add(new LineJudgment(26, 1, "Sơ Cửu", "初九:有厲,利已.", "Hữu lệ, lợi dĩ", "Hào Chín Đầu: Có nguy, lợi thôi.", 450, null));
        list.add(new LineJudgment(26, 2, "Cửu Nhị", "象⽈:有属利已,不犯災也. Dịch âm. - Tượng viết: Hữu lệ, lợi dĩ, bất phạm tai dã. Dịch nghĩa. - Lời Tượng nói rằng: Có nguy lợi thôi, chẳng phạm vào tai vạ vậy. GIẢI NGHĨA Truyện của Trình Di. - Có sự nguy thì nên thôi, không nên phạm vào vạ nguy mà đi. Chẳng lượng cái thế của mình mà đi, tất nhiên có nguy. LỜI KINH 九⼆: 輿說輻", "Dư thoát bức.", "Hào Chín Hai: Xe trút bánh.", 451, null));
        list.add(new LineJudgment(26, 3, "Cửu Tam", "九三:良⾺逐,利難貞,⽈賢輿衡,利有攸往.", "Lương mã trục, lợi gian trinh, nhật nhàn dư vệ, lợi hữu du vàng.", "Hào Chín Ba: Ngựa hay ruổi, ngày quen xe, lại có thửa đi.", 452, null));
        list.add(new LineJudgment(26, 4, "Lục Tứ", "象⽈: 利有攸往, 上志合也. Dịch âm. - Tượng viết: Lợi hữu du vãng, thựợng chí hợp dã. Dịch nghĩa. - Lời Tượng nói rằng: Lợi có thửa đi, vì chí kẻ trên hợp vậy. GIẢI NGHĨA Truyện của Trình Di. - Sở dĩ lợi có thửa đi, vì nó với kẻ ở trên hợp bụng cùng nhau, Hào Chín Trên tính Dương phải tiến lên, vả lại ở chỗ sự chứa đã cùng cực, cho nên nó không xuống chứa hào Ba cùng hào này hợp bụng tiến lên.LỜI KINH 六四:童⽜之接, 元吉.", "Đồng ngưu chi cốc, nguyên cát.", "Hào Sáu Tư: Cái cùm trâu non, cả tốt.", 454, null));
        list.add(new LineJudgment(26, 5, "Lục Ngũ", "象⽈: 六四元吉, 有喜也. Dịch âm. - Tượng viết: Lục Tứ nguyên cát, hữu hỷ dã. Dịch nghĩa. - Lời Tượng nói rằng : Hào Sáu Tư cả tốt, có mừng vậy. GIẢI NGHĨA Truyện của Trình Di. - Ác của thiên hạ đã thịnh mà mới ngăn đón, thì trên phải nhọc về sự cấm chế, dưới phải hại về sự giết chóc cho nên ngăn chỉ ngay từ trước khi còn nhỏ, thì cả hay mà tốt, không phải nhọc mà không bị hại, cho nên đáng mừng. Hào Tư ngăn chỉ hào Đầu là vậy đó. LỜI KINH 六五: 猪⾗之⽛, 吉", "Phần thi chi nha, cát.", "Hào Sáu Năm: Nanh con lợn thiến, tốt.", 455, null));
        list.add(new LineJudgment(26, 6, "Thượng Cửu", "象⽈: 六五之吉,有慶也. Dịch âm. - Tượng viết: Lạc ngũ chi cát, hữu khánh dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái tốt của hào Sáu Năm, có phúc vậy. GIẢI NGHĨA Truyện của Trình Di. - Kẻ ở trên mà không biết mẹo ngăn cấm điều ác, dùng hình phạt nghiêm ngặt để chọi với lòng ham muốn của dân, thì hại nhiều mà không có công. Nếu biết cái gốc của nó, chế nó có cách, thì chẳng nhọc, không hại, mà thói tục biến đổi, ấy là phúc khánh của thiên hạ. LỜI KINH上九: 何天之衢亨", "Hà thiên chí cù hanh.", "Hào Chín Trên: Sao đường trời hanh.", 457, null));

        // Que 27 (DI)
        list.add(new LineJudgment(27, 1, "Sơ Cửu", "初九:舍爾靈⿔, 觀我朵頤, 凶.", "Xả nhĩ linh quy, quan ngã đóa di, hung.", "Hào Chín Đầu: Bỏ con rùa thiêng của mày, xem ta trễ mép, hung!", 462, null));
        list.add(new LineJudgment(27, 2, "Lục Nhị", "象⽈: 觀我朵頤,亦不⾜貴也. Dịch âm. - Tượng viết: Quan ngã đóa đi, diệc bất túc quí dã. Dịch nghĩa. - Lời Tượng nói rằng: Xem ta trễ mép, cũng chẳng đủ quý vậy. GIẢI NGHĨA Truyện của Trình Di. - Hào Chín là thể động, trễ mép nghĩa là nó thích hào Âm mà chí động. Đã bị lòng dục làm động, thì tuy có tài cứng mạnh sáng khôn, rút lại cũng là tự mình đánh mất bản lĩnh của mình cho nên tài nó cũng không đủ quý. LỜI KINH 六⼆: 顛頤, 狒經于丘,征凶.", "Điên di, phất kinh vu khâu, chinh hung dã.", "Hào Sáụ Hai: Đảo nuôi, trái thường ở gò, đi thì hung.", 464, null));
        list.add(new LineJudgment(27, 3, "Lục Tam", "象⽈: 六⼆征凶, ⾏失類也. Dịch âm. - Tượng viết: Lục Nhị chinh hung, hành thất loại dã. Dịch nghĩa. - Lời Tượng nói rằng: Hào sáu Hai đi thì hung, vì đi mất loài vậy. GIẢI NGHĨA Truyện của Trình Di. - Đi mà theo hào Trên thì hung, là vì không phải loài nó. Đi tìm mà mất loài mình, được hung là phải. Bản nghĩa của Chu Hy. - Hào Đầu hào Trên đều không phải là loài của nó. LỜI KINH 六三: 拂頤, 貞凶, ⼗年勿⽤, 無攸利.", "Phất di, trinh hung, thập niên vật dụng, vô du lợi.", "Hào Sáu Bã: Trái nuôi, chính hung, mười năm chớ dùng, không thửa lợi.", 465, null));
        list.add(new LineJudgment(27, 4, "Lục Tứ", "象⽈: ⼗年勿⽤, 道⼤悖也. Dịch âm. - Tượng viết: Thập niên vật dụng, đạo đại bội dã. Dịch nghĩa. - Lời Tượng nói rằng: Mười năm chớ dùng, đạo cả trái vậy. GIẢI NGHĨA Truyện của Trình Di. - Sở dĩ phảỉ răn mười năm chớ dùng là vì cái đạo nó theo, rất trái nghĩa lý. LỜI KINH 六四: 顛頓, 吉.虎視眈眈, 其欲逐逐, 無咎.", "Điên di, cát, hổ thị đam đam, kỳ dục trục trục vô cữu.", "Hào Sáu Tư: Đảo nuôi, tốt, hổ trông hau háu, lòng muốn của nó liền liền, không lỗi.", 466, null));
        list.add(new LineJudgment(27, 5, "Lục Ngũ", "象⽈: 顛頤之吉, 上施光也. Dịch âm. - Tượng viết: Điên di chi cát, thượng thí quang dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái tốt của sự đảo nuôi, vì ơn trên sáng vậy. GIẢI NGHĨA Truyện của Trình Di. - Điên đảo của nuôi mà sở dĩ tốt, là vì được kẻ Dương cương ứng với, để làm nên việc, khiến cho ân đức của mình, là người ở trên, sáng tỏ chùm khắp thiên hạ, sự tốt gì lớn hơn thế? LỜI KINH 六五: 拂經, 居貞吉, 不可涉⼤川", "Phất kinh, cư trinh cát, bất khả thiệp đại xuyên.", "Hào Sáu Năm: Trái thường, ở chính tốt, chăng khá sang sông lớn.", 468, null));
        list.add(new LineJudgment(27, 6, "Thượng Cửu", "象⽈: 居貞之吉, 順以從上也. Dịch âm. - Tượng viết: Cư trinh chi cát, thuận dĩ tòng thượng dã. Dịch nghĩa. - Lời Tượng nói rằng: Cái tốt của sự ở chính, vì thuận theo trên vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở chính mà tốt, ý nói nó biết kiên cố thuận theo người hiền Chín Trên để nuôi thiên hạ. LỜI KINH 上九: 由頤, 厲, 吉, 利涉⼤川.", "Do di, lệ, cát, lợi thiệp đại xuyên.", "Hào Chín Trên: Bởi nuôi, nguy, tốt, lợi sang sông lớn.", 469, null));

        // Que 28 (ĐẠI QUÁ)
        list.add(new LineJudgment(28, 1, "Sơ Lục", "初六: 藉⽤⽩茅, 無咎.", "Tạ dụng bạch mao, vô cữu.", "Hào Sáu Đầu: Trải dùng cỏ tranh trắng, không lỗi.", 476, null));
        list.add(new LineJudgment(28, 2, "Cửu Nhị", "象⽈: 藉⽤⽩茅, 柔在下也. Dịch âm. - Tượng viết: Tạ dụng bạch mao, nhu tại hạ dã. Dịch nghĩa. - Lời Tượng nói rằng: Trải dùng cỏ tranh trắng, mềm ờ dưới vậy. GIẢI NGHĨA Truyện của Trình Di. - Cái đạo lấy chất Âm mềm ở chỗ thấp kém chỉ nênquá về kính cẩn mà thôi. Lấy chất mềm ở chỗ thấp là tượng dùng cỏ tranh trải vào vật khác, đó là đạo kính cẩn vậy. LỜI KINH 九⼆: 枯楊⽣梯, ⽼夫得其⼥妻, 無不利.", "Khô dương sinh đề, lão phu đắc kỳ nữ thê vô bất lợi.", "Hào Chín Hai: Cây Dương khô mọc rễ, chồng già được vợ con gái, không gì không lợi.", 477, null));
        list.add(new LineJudgment(28, 3, "Cửu Tam", "象⽈: ⽼夫⼥妻, 過以相與也. Dịch âm. - Tượng viết: Lão phu nữ thê, quá dĩ tương dữ dã, Dịch nghĩa. - Lời Tượng nói rằng: Chồng già vợ con gái, quá độ cùng nhau vậy. GIẢI NGHĨA Truyện của Trình Di. - Chồng già mà thích gái trẻ, gái trẻ thuận theo chồng già, sự cùng nhau của họ phải quá phận thường. Đó là chỉ về hào Chín Hai và hào Sáu Đầu Âm Dương hòa hợp với nhau, quá độ thường vậy. LỜI KINH 九三: 棟橈, 凶.", "Đống nạo hung!", "Hào Chín Ba: Cột ỏe, hung!", 478, null));
        list.add(new LineJudgment(28, 4, "Cửu Tứ", "象⽈: 棟橈之凶, 不可以有辅也. Dịch âm. - Tượng viết: Đống nạo chi hung, bất khả dĩ hữu phụ dã. Dịch nghĩa. - Lời Tượng nói rằng: Cột ỏe mà hung, là vì chẳng khá có giúp vậy. GIẢI NGHĨA Truyện của Trình Di. - Kẻ cương cường quá không thể theo người, người cũng không gần gũi giúp đỡ cho mình, như cột ỏe gẫy không thể chống đỡ. Cột ở giữa nhà, không thể thêm được cái gì giúp đỡ cho nó. Đó là chẳng khá có giúp. LỜI KINH 九四:棟隆, 吉, 有它, 吝.", "Đống long cát, hữu tha, lận.", "Hào Chín Tư: cột cao, tốt; có khí khác, đáng tiếc.", 479, null));
        list.add(new LineJudgment(28, 5, "Cửu Ngũ", "象⽈:棟隆之吉, 不橈乎下也. Dịch âm. - Tượng viết: Đống long chi cát, bấthạo hồ hạ dã. Dịch nghĩa. - Lời Tượng nói rằng: Cột cạo mà tốt, là vì chẳng ỏe ở dưới vậy. GIẢI NGHĨA Truyện của Trình Di. - Cột cao vọi lên thì tốt, vì không cong ỏe xuống dưới, ý nói nó không xuống mà buộc với hào Đầu. LỜI KINH 九五:枯楊⽣莓, ⽼婦得其⼠夫, 無咎無譽.", "Khô dương sinh huê, lão phụ đác kỳ sỹ phu, vô cữu vô dự.", "Hào Chín Năm: Cây dương khô mọc hoa, vợ già được chồng con trai, không lỗi không khen.GIẢI NGHĨA Truyện của Trình Di. - Hào Chín Năm thì cả quá, vốn là kẻ lấy đức trung chính ở ngôi tôn, nhưng vì phía dưới không có ứng giúp, chỉn không thể làm nên cái công cả quá, mà ở phía trên lại liền với hào Âm quá cực, thì sự giúp lẫn, cũng giống như cây dương khố mọc hoa. Cây dương khô mọc rễ ở dưới thì nó lại sống, như khi Dương cả quá, dấy nên sự công. Trên mọc hoa, tuy có mọc đó mà không ích gì cho sự khô. Hào Sáu Trên là Âm quá cực, tức là vợ già. Hào Năm tuy không phải trẻ, nhưng ví với vợ già, thì còn là hạng chồng tráng kiện. Vì hào Chín Năm không nhờ gì ở hào Sáu Trên, cho nên nói là “vợ được”. Khí Âm quá cực mà được khí Dương giúp cho, không phải vô ích. Là chồng con trai mà được vợ già, dẫu không tội lỗi, chỉn chẳng phải đẹp, cho nên nói rằng không lỗi không khen, và lời Tượng lại bảo thế là đáng xấu hổ. Bản nghĩa của Chu Hy. - Hào Chín Năm là Dương quá cực, lại liền nhau với hào Âm quá cực, cho nên Tượng, Chiêm của nó đều trái với hào Hai.", 480, null));
        list.add(new LineJudgment(28, 6, "Thượng Lục", "上六:過涉滅頂, 凶,無咎.", "Quả thiệp, diệt đính, hung, vô cữu.", "Hào Sáu Trên: Quá lội ngập đỉnh đầu, hung, không lỗi.", 481, null));

        // Que 29 (TẬP KHẢM)
        list.add(new LineJudgment(29, 1, "Sơ Lục", "初六:習坎, 如⾬坎窗, 凶.", "Tập Khảm, nhập vu Khảm tăm hung!", "Hào Sáu Đầu: Chỗ hiểm kép, vào cái hố trong chỗ hiểm, hung!", 487, null));
        list.add(new LineJudgment(29, 2, "Cửu Nhị", "象⽈:習坎⼊坎, 失道, 凶也. Dịch âm. - Tượng viết: Tập Khảm nhập Khảm, thất đạo hung dã. Dịch nghĩa. - Lời Tượng nói rằng: Từ chỗ hiểm kép vào chỗ hiểm, lạc đường, hung vậy. GIẢI NGHĨA Truyện của Trình Di. - Tự chỗ hiểm kép lại vào cái hố trong chỗ hiểm, đó là lạc đường, thế cho nên hung. Có thể ra khỏi chỗ hiểm, mới là không lạc đường. LỜI KINH 九⼆:坎有險, 求⼩得.", "Khảm hữu hiềm, cầu tiểu đắc.", "Hào Chín Hai: Chỗ trũng có sự hiểm, tìm hơi được.", 487, null));
        list.add(new LineJudgment(29, 3, "Lục Tam", "象⽈:求⼩得, 未出中也. Dịch âm. - Tượng viết: Cầu tiểu đắc, vị xuất trung dã. Dịch nghĩa. - Lời Tượng nói rằng: Tìm hơi được, là chưa ra khỏi bên trong vậy. GIẢI NGHĨA Truyện của Trình Di. - Đương hai lần hiểm nó hãm, ở vào chỗ hiểm nghèo, vì tài cứng giữa, không bị sa vào chỗ sâu hiểm, đó là sở cầu hơi được, nhưng mà vẫn chưa ra khỏi nơi hiểm nghèo trong chỗ hiểm. LỜI KINH 六三:來之坎坎, 險且枕, ⼊于坎窖, 物⽤.", "Lai chi khảm khảm, hiền thả chẩm, nhập vu khảm tãm,vật dụng.", "Hào Sáu Ba: Lại đi hiểm hiểm, hiểm vào gối, vào cái hố của hiểm, chớ dùng.", 488, null));
        list.add(new LineJudgment(29, 4, "Lục Tứ", "象⽈:來之坎坎, 終無功也. Dịch âm. - Tượng viết: Lai chi khảm khảm, chung vô công dã. Dịch nghĩa. - Lời Tượng nói rằng: Lại đi hiểm hiểm, rút lại không công vậy. GIẢI NGHĨA Truyện của Trình Di. - Tiến lui đều hiểm, ở lại không yên, nếu dùng đạo đó thì càng vào mãi chỗ hiểm, rút lại há thành công được? Lấy chất Âm mềm ở chỗ không trung chính, dù là đất bình dị, còn phải ăn năn, tội lỗi, huống chi là ở chỗ hiểm. Hiểm là nơi mà người ta muốn cho ra khỏi ắt phải được đường, thì mới lìa bỏ được nó. Cầu bỏ chỗ hiểm mà lại trái đường thì càng khốn cùng, cho nên thánh nhân mới răn như hào Ba đó không thể dùng được. LỜI KINH 六四: 得酒, 簋貳,⽤⽸, 納約⽩牖,终無咎.", "Tôn tửu, quỹ nhị, dụng phẫu, nạp ước tự dũ chung vô cữu.", "Hào Sáu Tư: Chén rượu, rá[6] xôi, thêm dùng hồ sành, nộp ước tự cửa sổ tròn, sau chót không lỗi.", 490, null));
        list.add(new LineJudgment(29, 5, "Cửu Ngũ", "象⽈:撙酒簋表, 剛柔際也. Dịch âm. - Tượng viết: Tôn tửu quĩ nhị, cương nhu tế dã. Dịch nghĩa. - Lời Tượng nói rằng: Chén rượu, rá đồ ăn, hai, cứng mềm giúp nhau vậy. GIẢI NGHĨA Truyện của Trình Di. - Chỉ nhắc câu đầu, như thế cũng nhiều rồi. Một chén rượu, hai rá đổ ăn, đó là mộc mạc thật thà đến tột bậc tức là cách cứng mềm tiếp tế với nhau. Có thể như thế, thì sẽ giữ được không lỗi. Sự giao tế của vua tôi được bền chặt và thường thường (lúc nào cũng như lúc nào) cốt ở thành thực mà thôi. Cứng mềm chỉ về hào Tư và hào Năm, tức là sự giao tế của vua tôi vậy. Bản nghĩa của Chu Hy. - Họ Triều nói rằng: Sách Thích văn của họ Lục đoạn này vốn không có chữ 貳 (nhị), nay theo đó.LỜI KINH 九五:坎不盈, 柢既平, 無咎.", "Khảm bất doanh, chỉ ký bình, vô cữu.", "Hào Chín Năm: Chỗ trũng chẳng đầy, đến đã phẳng, không lỗi.", 493, null));
        list.add(new LineJudgment(29, 6, "Thượng Lục", "象⽈:坎不盈, 中未⼤也. Dịch âm. - Tượng viết: Khảm bất doanh, trung vị đại dã. Dịch nghĩa. - Lời Tượng nói rằng: Chỗ trũng chẳng đầy, vi đức giữa chưa lớn vậy.GIẢI NGHĨA Truyện của Trình Di. - Hào Chín Năm là tài cứng giữa mà được ngôi tôn, nên phải làm cho thiên hạ vượt qua chỗ hiểm nạn, thế mà chỗ trũng còn chưa đầy, chưa thể bình được sự hiểm nạn, đó là cái đạo cứng giữa của nó chưa được sáng lớn vậy. Bản nghĩa của Chu Hy. - Có đức giữa mà chưa được lớn. LỜI KINH 上六:系⽤微纏, 寘于叢棘,三歲不得, 凶.", "Hệ dụng huy chiền, chỉ vu tòng cức, tam tuế bất đắc, hung!", "Hào Sáu Trên: Trói dùng chạc thừng, đặt ở bụi gai, ba năm chẳng được, hung!", 494, null));

        // Que 30 (LY)
        list.add(new LineJudgment(30, 1, "Sơ Cửu", "初九:履錯然, 敬之無咎.", "Lý thác nhiên, kinh chi vô cữu.", "Hào Chín Đầu: Xéo bừa vậy, kính đó không lỗi.", 499, null));
        list.add(new LineJudgment(30, 2, "Lục Nhị", "象⽈:履錯之敬, 以辟咎也. Dịch âm. - Tượng viết: Lý thác chi kính, dĩ tựu cữu dã. Dịch nghĩa. - Lời Tượng nói rằng: Sự kính của kẻ xéo bừa, để tránh lỗi vậy. GIẢI NGHĨA Truyện của Trình Di. - Xéo bừa muốn động, mà biết kính cẩn không dám tiến lên, là để cầu tránh cho khỏi lầm lỗi vậy. LỜI KINH 六⼀:黄雜,元吉.", "Hoàng Ly, nguyên cát.", "Hào Sáu Hai: Vàng sáng, cả tốt.", 500, null));
        list.add(new LineJudgment(30, 3, "Cửu Tam", "象⽈: 黄雜元吉, 得中道也Dịch âm. - Tượng viết: Hoàng Ly nguyên cát, đắc trung đạo dã. Dịch nghĩa. - Lời Tượng nói rằng : Vàng sáng cả tốt, được đạo giữa vậy. GIẢI NGHĨA Truyện của Trình Di. - Sở dĩ cả tốt, là vì nó được đạo giữa. LỜI KINH 九三:⽇昃之難, 不⿎⽸⽽歌, 則⼤聋之嗟,凶.", "Nhật trắc chi ly, bất cỗ phẫu nhị nhi ca, tắc đại diệt chi ta, hung!", "Hào Chín Ba: Sự sáng của mặt trời dé. Chẳng gõ chậu sành mà hát, thì là cả già mà than, hung!", 501, null));
        list.add(new LineJudgment(30, 4, "Cửu Tứ", "象⽈: ⽇昃之難, 何可久也. Dịch âm. - Tượng viết: Nhật trắc chi ly, hà khả cữu dà? Dịch nghĩa. - Lời Tượng nói rằng: Sự sáng của mặt trời dé, sao khá lâu vậy? GIẢI NGHĨA Truyện của Trình Di. - Mặt trời đã nghiêng dé, sự sáng còn lâu được sao? Kẻ sáng biết nó thế, cho nên tìm người để nối việc mình, lui về mà ở để nghỉ thân mình, yên lẽ thường, xử cách thuận, sao đủ là hung? LỜI KINH 九四: 突如,其來如,焚如, 死如, 棄如.", "Đột như kỳ lai như, phần như, tử như, khí như!", "Hào Chín Tư: Đột như thửa lai vậy, cháy vậy, chết vậy, bỏ vậy!", 502, null));
        list.add(new LineJudgment(30, 5, "Lục Ngũ", "象⽈:突如其來如, 無所容也. Dịch âm. - Tượng viết: Đột như kỳ lai như, vô sở dung dã. Dịch nghĩa. - Lời Tượng nói rằng: Đột nhiên thửa lại, là không có chỗ dung vậy. GIẢI NGHĨA Truyện của Trình Di. - Trên thì lấn vua, không chịu thuận với kẻ mà mình phải vâng theo, ấy là mọi người ghét bỏ, thiên hạ không dung. Bản nghĩa của Chu Hy. - Không có chỗ dong là nói bị cháy, chết, bỏ. LỜI KINH 六五: 涕沱若, 嗟若, 吉.", "Thế đà nhược! Thích ta nhược! Cát!", "Hào Sáu Năm: Nước mắt giàn giụa vậy, ngậm ngùi than vậy, tốt!", 503, null));
        list.add(new LineJudgment(30, 6, "Thượng Cửu", "象⽈:六五之吉, 灕王公也. Dịch âm. - Tượng viết: Lục Ngũ chi cát, ly vương công dã. Dịch nghĩa. - Lời tượng nói rằng: Sự tốt của hào Sáu Năm, là được bám vào tước vương tước công vậy. GIẢI NGHĨA Truyện của Trình Di. - Cái tốt của hào Sáu Năm, vì chỗ nó bám là ngôi chính của tước vương công. Bởi nó chiếm thế “ở trên” mà lại xét rõ sự lý, sợ hãi lo lắng để giữ gìn, cho nên được tốt. LỜI KINH 上九:王⽤出征, 有嘉, 折⾸, 獲匪其醜, 無咎.", "Vương dụng xuất chinh, hữu giá, chiết thủ, hoạch phi kỳ sũ, vô cữu.", "Hào Chín Trên: Vua dùng ra đánh, có sự tốt, bẻ đầu, bắt chẳng phải loài, không lỗi.", 504, null));

        // Que 31 (HÀM)
        list.add(new LineJudgment(31, 1, "Sơ Lục", "初六: 咸其拇", "Hàm kỳ mẫu.", "Hào Sáu Đầu: Cảm thửa ngón chân cái.", 512, null));
        list.add(new LineJudgment(31, 2, "Lục Nhị", "象⽈:咸其拇, 志在外也. Dịch âm. - Tượng viết: Hàm kỳ mẫu, chí tại ngoại dã. Dịch nghĩa. - Lời Tượng nói rằng: Cảm thửa ngón chân cái, chí ở ngoài vậy. GIẢI NGHĨA Truyện của Trình Di. - Chí của hào Đầu mà động, là cảm với hào Tư, cho nên nói là “ở ngoài”. Chí tuy động mà cảm chưa sâu, chưa đủ để tiến lên. LỜI KINH六⼆:咸其腓,凶,居吉.", "Hàm kỳ phi, hung! cư cắt!", "Hào Sáu Hai: Cảm thửa bụng chân hung! Ở yên, tốt!", 513, null));
        list.add(new LineJudgment(31, 3, "Cửu Tam", "象⽈, 雖凶,居吉,順不害也. Dịch âm. - Tượng viết: Tuy hung, cư cát, thuận bất hại dã. Dịch nghĩa. - Lời Tượng nói rằng: Dẫu hung, ở yên tốt, thuận thì không hại vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở giữa được chỗ chính, ứng với nó lại cũng là kẻtrung chính, tài nó vốn là lương thiện, vì ở thì “cảm”, chất mềm mà ứng lên trên, cho nên răn rằng: Hễ động trước mà đi tìm vua thì hung, ở yên mà tự giữ đạo thì tốt; lời Tượng lại nói cho rõ ý đó mà rằng: “Không phải răn rằng không được cảm nhau, chỉ có thuận lễ thì không có hại. Thuận lễ nghĩa là giữ đạo đừng động trước vậy. LỜI KINH 九三:咸其股,執其雖,往吝.", "Hàm kỳ cổ, chấp kỳ tùy, vãng lận.", "Hào Chính Ba: Cảm thửa đùi, giữ thửa sự theo, đi thì đáng tiếc.", 514, null));
        list.add(new LineJudgment(31, 4, "Cửu Tứ", "象⽈:咸其股,亦不處也,志在隨⼈,所執下也. Dịch âm. - Tượng viết: Hàm kỳ cổ, diệc bất xử dã, chí tại tùy nhân, sở chấp hạ dã. Dịch nghĩa. - Lời Tượng nói rằng: Cảm thửa đùi, cùng chẳng ở vậy: Chí ở theo người, thửa giữ thấp vậy. GIẢI NGHĨA Truyện của Trình Di. - Có chất Dương cứng, không biết tự giữ, chí lại thích theo người ta, ấy là sự cầm giữ của nó rất hèn thấp vậy. Bản nghĩa của Chu Hy. - Nói là “cũng” vì hai hào trước đều muốn động cả. Hai hào Âm vốn tính nóng nẩy, nó động là phải, hào Chín Ba là chất Dương cứng, ở chỗ cùng cực sự đậu, nên tĩnh thì phải, mà cũng lại động, là đáng tiếc lắm. LỜI KINH 九四:貞吉,悔亡,憧撞往來,朋從爾志,", "Trinh cát, hối vong, đồng vãng lai, bằng tòng nhĩ tư.", "Hào Chín Tư: Chính bền thì tốt, sự ăn năn sẽ mất; săng sắc đi lại, bạn theo sự nghĩ của mày.", 515, null));
        list.add(new LineJudgment(31, 5, "Cửu Ngũ", "象⽈:貞其悔亡,未感害美也,憧憧往來,未光六也. Dịch âm. - Tượng viết Trinh cát, hối vong, vị cảm hại dã, đồng đồng vãng lại, vị quang đại dã. Dịch nghĩa. - Lời Tượng nói rằng: Chính tốt, sự ăn năn mất, chưa cảm hại vậy, săng sắc đi lại, chưa sáng lớn vậy. GIẢI NGHĨA Truyện của Trình Di. - Chính bền thì sự ăn năn phải mất, đó là chưa bị sự cảm riêng làm hại; hễ là ứng riêng thì có hại cho sự cảm, săng săng sắc đi lại, là lấy lòng riêng cảm nhau, đạo cảm đẹp rồi, cho nên nói là chưa sáng lớn. Bản nghĩa của Chu Hy. - Cảm hại nghĩa là lấy sự bất chính mà cảm thì có hại vậy. LỜI KINH 九五:咸其腮,無悔.", "Hàm kỳ môi, vô hối.", "Hào Chín Năm: Cảm thửa thăn thịt, không ăn năn.GIẢI NGHĨA Truyện của Trình Di. - Hào Chín Năm là ngôi tôn, nên lấy lòng chí thành để cảm thiên hạ mà ứng với hào Hai, liền với hào Trên, nếu vướng víu với hào Hai mà đẹp lòng với hào Trên, thì thiên tử nông hẹp, không phải là đạo kẻ làm vua, há cảm được thiên hạ? Thăn thịt là thịt lưng trái nhau với tim, mắt không trông thấy. Ý nói: nếu trái được lòng riêng, kẻ cảm thông phải là người mình đã trông thấy mà đẹp lòng, thì được chính đạo của kẻ làm vua cảm thiên hạ mà không có sự ăn năm. Bản nghĩa của Chu Hy. - Thăn thịt tức là thịt lưng, ở khoảng trên tim mà nó trái nhau với tim, không thể cảm vật, chẳng vướng víu về sự riêng tây, Hào Chín Năm vừa nhằm chỗ đó, cho nên dùng làm Tượng mà răn kẻ xem: hễ mà có thể như thế, thì tuy không cảm được người nhưng cũng có thể không phải ăn năn.", 517, null));
        list.add(new LineJudgment(31, 6, "Thượng Lục", "象⽈:咸其,志未也 Dịch âm. - Tượng viết: Hàm kỳ môi, chí mạt[6] dã. Dịch nghĩa. - Lời Tượng nói rằng: Cảm thửa thăn thịt, chí ngọn vậy. Truyện của Trình Di. - Đây là răn bảo người ta, khiến họ trái với lòng riêng mà cảm thăn thịt, vì họ để bụng về đường nông nổi, vút ngọn, vướng víu hào Hai mà đẹp lòng với hào Trên, đố là cảm về tư dục của mình. Bản nghĩa của Chu Hy. - Chí ngọn nghĩa là không thể cảm người. Lời bàn của Tiên Nho. - Hồ Vân Phong nói rằng: Hào Đầu nói rằng: “chí ở ngoài”, hào Ba nói rằng: “chí ở theo người” hào Năm tuy không vướng víu lòng riêng, không thể cảm người, nhưng mà chí nó như thế cùng nhỏ nhặtlắm. LỜI KINH 上六:咸其辅,頰,⾆.", "Hàm kỳ phụ, giáp, thiệt.", "Hào Sáu Trên: Cảm thửa xương má, mép, lưỡi.", 519, null));

        // Que 32 (HẰNG)
        list.add(new LineJudgment(32, 1, "Sơ Lục", "象⽈:雷⾵恆,君⼦以⽴不易⽅. Dịch âm. - Tượng viết: Lôi phong Hằng, quân tử dĩ lập bất dịch phương. Dịch nghĩa. - Lời Tượng nói rằng: Sấm gió là quẻ Hằng, đấng quân tử coi đó mà đứng chẳng đổi phương. GIẢI NGHĨA Truyện của Trình Di. - Đấng quân tử coi tượng sấm gió cùng nhau làm thành quẻ Hằng, để giữ cho đức của mình thường lâu, tự đứng trên đường trung chính thường lâu, không đổi phương sở. LỜI KNH 初六:泼情,員凶,無攸利.", "Tuấn Hằng, trinh hung, vô du lợi.", "Hào Sáu Đầu: Đào sâu sự thường, trinh cũng hung, không thửa lợi.", 526, null));
        list.add(new LineJudgment(32, 2, "Cửu Nhị", "象⽈:浚情志凶,始求深也. Dịch âm. - Tượng viết: Tuấn hằng chi hung, thủy cầu thâm dã. Dịch nghĩa. - Lời Tượng nói rằng: Đào sâu sự thường mà hung, mới cầu sâu vậy. GIẢI NGHĨA Truyện của Trình Di. - Ở lúc mới đầu của đạo Hằng, mà cầu mong người trên một cách sâu sắc, ấy chỉ là biết thói thường mà không biết đo đắn tình thế, vì vậy mới hung. LỜI KINH 九⼆:悔亡.", "Hối vong.", "Hào Chín Hai: Sự ăn năn mất.", 527, null));
